#import "SLAPI.h"
#import "SLAuthStore.h"
#import <CoreFoundation/CoreFoundation.h>
@interface SLAPI ()
- (void)tryPages:(NSString *)slug chapter:(NSDictionary *)chapter site:(NSInteger)site branches:(NSArray *)branches index:(NSUInteger)index lastError:(NSError *)lastError completion:(SLAPICompletion)completion;
@end
@implementation SLAPI
+ (SLAPI *)shared { static SLAPI *s=nil;if(!s)s=[[SLAPI alloc]init];return s; }
- (NSString *)encoded:(NSString *)s { CFStringRef value=CFURLCreateStringByAddingPercentEscapes(NULL,(CFStringRef)(s?:@""),NULL,CFSTR(":/?#[]@!$&'()*+,;=%"),kCFStringEncodingUTF8);return [(NSString *)value autorelease]; }
- (void)get:(NSString *)path query:(NSDictionary *)query site:(NSInteger)site completion:(SLAPICompletion)completion {
 NSMutableString *u=[NSMutableString stringWithFormat:@"https://api.lib.social/api%@",path];if([query count]){[u appendString:@"?"];NSArray *keys=[[query allKeys]sortedArrayUsingSelector:@selector(compare:)];BOOL first=YES;for(NSString *k in keys){id v=[query objectForKey:k];NSArray *vs=[v isKindOfClass:[NSArray class]]?v:[NSArray arrayWithObject:v];for(id x in vs){if(!first)[u appendString:@"&"];first=NO;[u appendFormat:@"%@=%@",[self encoded:k],[self encoded:[x description]]];}}}
 NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:u] cachePolicy:NSURLRequestReloadIgnoringLocalCacheData timeoutInterval:35];[r setValue:[NSString stringWithFormat:@"%ld",(long)(site?site:2)] forHTTPHeaderField:@"Site-Id"];[r setValue:@"application/json" forHTTPHeaderField:@"Accept"];NSString *token=[SLAuthStore siteToken];if([token length])[r setValue:[NSString stringWithFormat:@"Bearer %@",token] forHTTPHeaderField:@"Authorization"];[r setValue:(site==1?@"https://mangalib.me/":@"https://slashlib.me/") forHTTPHeaderField:@"Referer"];[r setValue:@"Mozilla/5.0 (iPhone; CPU iPhone OS 6_1 like Mac OS X) AppleWebKit/536.26 Mobile/10B141 Safari/8536.25" forHTTPHeaderField:@"User-Agent"];
 [NSURLConnection sendAsynchronousRequest:r queue:[[[NSOperationQueue alloc]init]autorelease] completionHandler:^(NSURLResponse *resp,NSData *data,NSError *err){id obj=nil;NSError *parse=nil;if(!err&&data)obj=[NSJSONSerialization JSONObjectWithData:data options:NSJSONReadingMutableContainers error:&parse];NSError *out=err?:parse;NSInteger status=[(NSHTTPURLResponse *)resp statusCode];if(!out&&status>=400)out=[NSError errorWithDomain:@"SlashlibAPI" code:status userInfo:[NSDictionary dictionaryWithObject:[NSString stringWithFormat:@"Ошибка API (HTTP %ld)",(long)status] forKey:NSLocalizedDescriptionKey]];dispatch_async(dispatch_get_main_queue(),^{if(completion)completion(obj,out);});}];
}
- (void)search:(NSString *)q page:(NSInteger)page completion:(SLAPICompletion)c { NSArray *sites=[[NSUserDefaults standardUserDefaults]boolForKey:@"SLMangaLibEnabled"]?[NSArray arrayWithObjects:@"2",@"1",nil]:[NSArray arrayWithObject:@"2"];[self get:@"/manga" query:[NSDictionary dictionaryWithObjectsAndKeys:sites,@"site_id[]",q?:@"",@"q",[NSString stringWithFormat:@"%ld",(long)page],@"page",nil] site:2 completion:c]; }
- (void)chapters:(NSString *)slug site:(NSInteger)site completion:(SLAPICompletion)c {[self get:[NSString stringWithFormat:@"/manga/%@/chapters",[self encoded:slug]] query:nil site:site completion:c];}
- (void)pages:(NSString *)slug chapter:(NSDictionary *)ch site:(NSInteger)site completion:(SLAPICompletion)c {NSArray *branches=[ch objectForKey:@"branches"];NSMutableArray *attempts=[NSMutableArray array];for(id b in branches){id bid=[b isKindOfClass:[NSDictionary class]]?[b objectForKey:@"branch_id"]:b;if(bid)[attempts addObject:bid];}if(![attempts count]&&[[ch objectForKey:@"branchIds"]isKindOfClass:[NSArray class]])[attempts addObjectsFromArray:[ch objectForKey:@"branchIds"]];[attempts addObject:[NSNull null]];[self tryPages:slug chapter:ch site:site branches:attempts index:0 lastError:nil completion:c];}
- (void)tryPages:(NSString *)slug chapter:(NSDictionary *)ch site:(NSInteger)site branches:(NSArray *)branches index:(NSUInteger)i lastError:(NSError *)lastError completion:(SLAPICompletion)c {if(i>=[branches count]){if(c)c(nil,lastError?:[NSError errorWithDomain:@"SlashlibAPI" code:404 userInfo:[NSDictionary dictionaryWithObject:@"В этой главе нет доступных страниц" forKey:NSLocalizedDescriptionKey]]);return;}NSMutableDictionary *q=[NSMutableDictionary dictionary];if([ch objectForKey:@"volume"])[q setObject:[ch objectForKey:@"volume"] forKey:@"volume"];if([ch objectForKey:@"number"])[q setObject:[ch objectForKey:@"number"] forKey:@"number"];id branch=[branches objectAtIndex:i];if(branch!=[NSNull null])[q setObject:branch forKey:@"branch_id"];NSString *path=[NSString stringWithFormat:@"/manga/%@/chapter",[self encoded:slug]];[self get:path query:q site:site completion:^(id root,NSError *error){NSArray *pages=[[root objectForKey:@"data"]objectForKey:@"pages"];if(!error&&[pages isKindOfClass:[NSArray class]]&&[pages count]){if(c)c(root,nil);}else [self tryPages:slug chapter:ch site:site branches:branches index:i+1 lastError:error?:lastError completion:c];}];}
- (void)details:(NSString *)slug site:(NSInteger)site completion:(SLAPICompletion)c {[self get:[NSString stringWithFormat:@"/manga/%@",[self encoded:slug]] query:[NSDictionary dictionaryWithObject:[NSArray arrayWithObjects:@"summary",@"genres",@"tags",nil] forKey:@"fields[]"] site:site completion:c];}
- (void)me:(SLAPICompletion)c {[self get:@"/auth/me" query:nil site:2 completion:c];}
- (void)catalogPage:(NSInteger)page genreID:(NSNumber *)genreID completion:(SLAPICompletion)c {NSArray *sites=[[NSUserDefaults standardUserDefaults]boolForKey:@"SLMangaLibEnabled"]?[NSArray arrayWithObjects:@"2",@"1",nil]:[NSArray arrayWithObject:@"2"];NSMutableDictionary *q=[NSMutableDictionary dictionaryWithObjectsAndKeys:sites,@"site_id[]",[NSString stringWithFormat:@"%ld",(long)page],@"page",nil];if(genreID)[q setObject:genreID forKey:@"genres[]"];[self get:@"/manga" query:q site:2 completion:c];}
- (void)genres:(SLAPICompletion)c {[self get:@"/constants" query:[NSDictionary dictionaryWithObject:[NSArray arrayWithObject:@"genres"] forKey:@"fields[]"] site:2 completion:c];}
@end
